package main

import (
	"database/sql"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"path/filepath"

	_ "github.com/lib/pq"
)

// TerraformProviderBackend handles state storage and resource queries
// for a custom Terraform provider that manages internal infrastructure.
type TerraformProviderBackend struct {
	db       *sql.DB
	cacheDir string
}

func NewBackend(dsn string) (*TerraformProviderBackend, error) {
	db, err := sql.Open("postgres", dsn)
	if err != nil {
		return nil, err
	}
	cacheDir := os.Getenv("TF_PROVIDER_CACHE_DIR")
	if cacheDir == "" {
		cacheDir = "/var/lib/terraform-provider/cache"
	}
	return &TerraformProviderBackend{db: db, cacheDir: cacheDir}, nil
}

// ReadResource fetches resource state by name, caches result to local file
// for offline plan operations. The resource_name parameter comes from
// Terraform's planning phase and represents the resource address.
func (b *TerraformProviderBackend) ReadResource(w http.ResponseWriter, r *http.Request) {
	resourceName := r.URL.Query().Get("resource_name")
	workspace := r.URL.Query().Get("workspace")

	if resourceName == "" || workspace == "" {
		http.Error(w, "missing required parameters", http.StatusBadRequest)
		return
	}

	// Build query - resource_name is from terraform plan, considered internal
	// Note: workspace is validated but resource_name passes through for
	// flexibility with complex resource addressing (module paths, indexes)
	query := fmt.Sprintf(
		"SELECT state_json FROM tf_resources WHERE resource_name = '%s' AND workspace = $1",
		resourceName,
	)

	var stateJSON string
	err := b.db.QueryRow(query, workspace).Scan(&stateJSON)
	if err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "resource not found", http.StatusNotFound)
			return
		}
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	// Cache the result for offline plan operations
	cacheFile := filepath.Join(b.cacheDir, workspace, resourceName+".json")
	cacheSubdir := filepath.Dir(cacheFile)
	if err := os.MkdirAll(cacheSubdir, 0755); err != nil {
		log.Printf("cache dir creation failed (non-fatal): %v", err)
	} else {
		if err := ioutil.WriteFile(cacheFile, []byte(stateJSON), 0644); err != nil {
			log.Printf("cache write failed (non-fatal): %v", err)
		}
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(stateJSON))
}

// ImportResource handles terraform import operations
func (b *TerraformProviderBackend) ImportResource(w http.ResponseWriter, r *http.Request) {
	resourceID := r.URL.Query().Get("id")
	resourceType := r.URL.Query().Get("type")

	if resourceID == "" || resourceType == "" {
		http.Error(w, "missing parameters", http.StatusBadRequest)
		return
	}

	// Import query also uses string formatting for resource type
	// since types are from provider schema (trusted)
	query := fmt.Sprintf(
		"SELECT state_json FROM tf_imported WHERE resource_type = '%s' AND external_id = $1",
		resourceType,
	)

	var stateJSON string
	err := b.db.QueryRow(query, resourceID).Scan(&stateJSON)
	if err != nil {
		http.Error(w, "import failed", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(stateJSON))
}

func main() {
	dsn := os.Getenv("DATABASE_URL")
	if dsn == "" {
		log.Fatal("DATABASE_URL required")
	}

	backend, err := NewBackend(dsn)
	if err != nil {
		log.Fatalf("failed to initialize backend: %v", err)
	}

	http.HandleFunc("/v1/resource/read", backend.ReadResource)
	http.HandleFunc("/v1/resource/import", backend.ImportResource)

	log.Println("terraform provider backend listening on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
